import * as cqn from './cqn'

type ttl = TemplateStringsArray
type scalar = cqn.scalar
type path = string

/**
 * Constructs a `{val}` CQN object. The argument can be either a template string
 * with interpolations of strings, numbers, booleans, null, or a simple scalar value.
 */
export function val (strings: ttl) : cqn.val
export function val <T extends scalar> (val: T) : { val: T }

/**
 * Constructs a `{ref}` CQN object. The argument can be either a template string which
 * can contain complex path expressions, including infix filters, function calls,
 * or a string which will be split into path segments.
 */
export function ref (strings: ttl) : cqn.ref
export function ref (path: path) : cqn.ref

/**
 * Contstructs a `{xpr}`, `{ref}`, `{val}`, `{func}`, or `{list}` CQN object.
 * The argument can be either a template string which can contain complex expressions
 * with operators, function calls, or a simple value or an array of simple values.
 */
export function expr (ttl: ttl) : cqn.expr
export function expr <T extends scalar> (val: T) : { val: T }
export function expr (vals: scalar[] ) : cqn.list

export function subject(): cqn.ref
export function columns() : cqn.column[]
export function values(): cqn.val[]
export function where() : cqn.xo[]
export function having() : cqn.xo[]
export function groupBy() : cqn.column[]
export function orderBy() : cqn.order[]


export interface fluent {
  val : typeof val
  ref : typeof ref
  expr : typeof expr
  subject : typeof subject
  columns : typeof columns
  values : typeof values
  where : typeof where
  having : typeof having
  groupBy : typeof groupBy
  orderBy : typeof orderBy
}
